_SLUG_RE = re.compile(r"^[a-z0-9][a-z0-9._-]*$")


def _fail(message: str, json_output: bool, *, details: object | None = None) -> NoReturn:
    if json_output:
        payload: dict[str, Any] = {"ok": False, "error": message}
        if details is not None:
            payload["details"] = details
        click.echo(json.dumps(payload, indent=2, sort_keys=True))
    else:
        click.echo(f"Error: {message}", err=True)
    raise click.exceptions.Exit(1)


def _emit_checkpoint(
    project: AnalysisProject,
    json_output: bool,
    *,
    message: str,
    changed: bool | None = None,
    gate: GateReport | None = None,
    inventory: list[dict[str, Any]] | None = None,
    extra: dict[str, Any] | None = None,
) -> None:
    if json_output:
        payload = project.summary()
        payload["ok"] = getattr(gate, "ok", True)
        payload["message"] = message
        if changed is not None:
            payload["changed"] = changed
        if gate is not None:
            payload["gate"] = gate.to_dict()
        if inventory is not None:
            payload["upload_inventory"] = inventory
        if extra is not None:
            payload.update(extra)
        click.echo(json.dumps(payload, indent=2, sort_keys=True))
        return

    click.echo("[analysis checkpoint]")
    click.echo(f"project: {project.slug} ({project.project_id})")
    click.echo(f"stage: {project.stage}")
    click.echo(f"status: {project.status}")
    click.echo(f"revision: {project.revision}")
    click.echo(
        f"repo: {project.repo.name}@{project.repo.branch} ({project.repo.sha or 'uncommitted'})"
    )
    click.echo(f"next: {project.next_action or '-'}")
    click.echo(f"message: {message}")
    if gate is not None:
        click.echo(f"gate: {'pass' if gate.ok else 'blocked'}")
        for blocker in gate.blockers:
            click.echo(f"blocker: {blocker}")
    if inventory is not None:
        click.echo("upload inventory:")
        for item in inventory:
            click.echo(f"  {item['path']}  sha256:{item['sha256']}  {item['size_bytes']} bytes")
    if extra is not None:
        for key, value in extra.items():
            click.echo(f"{key.replace('_', ' ')}: {value}")


def _load_project(
    store: AnalysisProjectStore,
    directory: Path | None,
    json_output: bool,
) -> AnalysisProject:
    try:
        return store.load(directory) if directory else store.load_active()
    except AnalysisStateError as exc:
        _fail(str(exc), json_output)


def _normal_slug(value: str, json_output: bool) -> str:
    slug = value.strip().lower()
    if not _SLUG_RE.fullmatch(slug):
        _fail(
            "Slug must start with a letter or number and contain only "
            "lowercase letters, numbers, '.', '_' or '-'.",
            json_output,
        )
    return slug


def _exit_if_blocked(
    project: AnalysisProject,
    gate: GateReport,
    json_output: bool,
    message: str,
) -> None:
    _emit_checkpoint(project, json_output, message=message, changed=False, gate=gate)
    if not gate.ok:
        raise click.exceptions.Exit(1)


@click.group("guided-analysis", invoke_without_command=True)
@click.pass_context
def analysis_group(ctx: click.Context) -> None:
    """Private Claude helper for a persistent, checkpointed guided analysis."""
    if ctx.invoked_subcommand is None:
        click.echo(ctx.get_help())


@analysis_group.command("start")
@click.argument("slug")
@click.option(
    "--dir",
    "directory",
    required=True,
    type=click.Path(path_type=Path),
    help="Local topic directory.",
)
@click.option("--question", required=True, help="Research question for the analysis.")
@click.option("--repo", "--repo-name", "repo_name", default=None, help="Associated repo name.")
@click.option("--branch", "repo_branch", default="main", show_default=True)
@click.option("--sha", "repo_sha", default=None, help="Associated repo commit SHA.")
@click.option(
    "--legacy-import",
    is_flag=True,
    help="Explicitly import a pre-dynamic-contract project.",
)
@click.option("--json", "json_output", is_flag=True, help="Emit machine-readable JSON.")
def start_command(
    slug: str,
    directory: Path,
    question: str,
    repo_name: str | None,
    repo_branch: str,
    repo_sha: str | None,
    legacy_import: bool,
    json_output: bool,
) -> None:
    """Create a local project and make it active; no remote repo is created."""
    slug = _normal_slug(slug, json_output)
    question = question.strip()
    if not question:
        _fail("Question cannot be empty.", json_output)
    normalized_repo = (repo_name or slug).strip()
    normalized_branch = repo_branch.strip()
    if not normalized_repo:
        _fail("Repository name cannot be empty.", json_output)
    if not normalized_branch:
        _fail("Repository branch cannot be empty.", json_output)
    directory = directory.expanduser().resolve()
    if directory.exists() and not directory.is_dir():
        _fail(f"Topic path is not a directory: {directory}", json_output)
    try:
        directory.mkdir(parents=True, exist_ok=True)
    except OSError as exc:
        _fail(f"Cannot create topic directory {directory}: {exc}", json_output)

    store = AnalysisProjectStore()
    state_file = directory / "analysis_project.json"
    if state_file.exists():
        try:
            project = store.load(directory)
        except AnalysisStateError as exc:
            _fail(str(exc), json_output)
        same = (
            project.slug == slug
            and project.question == question
            and project.repo.name == normalized_repo
            and project.repo.branch == normalized_branch
            and project.repo.sha == repo_sha
            and project.legacy_import == legacy_import
            and Path(project.topic_dir).resolve() == directory
        )
        if not same:
            _fail(
                f"{directory} already contains a different analysis project "
                f"({project.slug}, {project.project_id}).",
                json_output,
            )
        try:
            store.set_active(directory)
        except AnalysisStateError as exc:
            _fail(str(exc), json_output)
        _emit_checkpoint(
            project,
            json_output,
            message="Existing matching project resumed.",
            changed=False,
        )
        return

    now = utc_now()
    project = AnalysisProject(
        project_id=str(uuid.uuid4()),
        slug=slug,
        topic_dir=str(directory),
        question=question,
        repo=RepositoryRef(
            name=normalized_repo,
            branch=normalized_branch,
            sha=repo_sha,
        ),
        legacy_import=legacy_import,
        created_at=now,
        updated_at=now,
    )
    project.next_action = next_action_for_stage(project)
    try:
        store.save(project, touch=False)
        store.set_active(directory)
    except AnalysisStateError as exc:
        _fail(str(exc), json_output)
    _emit_checkpoint(project, json_output, message="Analysis project started.", changed=True)


def _artifact_checklist(project: AnalysisProject) -> dict[str, bool]:
    """Check the current executable stage contract directly from disk."""
    topic = Path(project.topic_dir)
    return {name: (topic / name).is_file() for name in stage_artifacts(project)}


@analysis_group.command("status")
@click.option("--dir", "directory", type=click.Path(path_type=Path))
@click.option("--json", "json_output", is_flag=True, help="Emit machine-readable JSON.")
def status_command(directory: Path | None, json_output: bool) -> None:
    """Show the active or explicitly selected project."""
    project = _load_project(AnalysisProjectStore(), directory, json_output)
    if project.status != "awaiting_user":
        project.next_action = next_action_for_stage(project)
    checklist = _artifact_checklist(project)
    missing = [name for name, exists in checklist.items() if not exists]
    routine_name = os.environ.get("PAPERCLIP_ROUTINE_NAME", "paperclip-meta-analysis")
    extra: dict[str, Any] = {
        "artifact_checklist": checklist,
        "expected_artifacts": list(checklist),
        "current_artifacts": [name for name, exists in checklist.items() if exists],
        "reload_orchestrator": (f"paperclip routines show {routine_name}"),
    }
    if missing:
        extra["missing_artifacts"] = missing
        extra["artifact_warning"] = (
            f"Current {project.stage} checkpoint is missing: {', '.join(missing)}"
        )
    _emit_checkpoint(project, json_output, message="Project status.", extra=extra)


@analysis_group.command("review")
@click.argument(
    "stage",
    required=False,
    type=click.Choice(["question", "evidence", "results"]),
)
@click.option("--dir", "directory", type=click.Path(path_type=Path))
@click.option(
    "--stage",
    "stage_option",
    type=click.Choice(["question", "evidence", "results"]),
)
@click.option(
    "--refresh",
    is_flag=True,
    help="Rebuild evidence_review.json from current evidence-stage artifacts.",
)
@click.option(
    "--landmarks",
    "landmark_list",
    type=click.Path(path_type=Path),
    help="Optional landmark list inside the analysis project directory.",
)
@click.option("--json", "json_output", is_flag=True, help="Emit machine-readable JSON.")
def review_command(
    stage: str | None,
    directory: Path | None,
    stage_option: str | None,
    refresh: bool,
    landmark_list: Path | None,
    json_output: bool,
) -> None:
    """Validate required artifacts and frozen hashes for a checkpoint."""
    if stage and stage_option and stage != stage_option:
        _fail("Positional stage and --stage disagree.", json_output)
    store = AnalysisProjectStore()
    project = _load_project(store, directory, json_output)
    target = stage_option or stage or project.stage
    if landmark_list is not None and not refresh:
        _fail("--landmarks requires --refresh.", json_output)
    if refresh:
        if target != "evidence":
            _fail("--refresh is only valid for the evidence checkpoint.", json_output)
        try:
            verified_path = Path(project.topic_dir) / "verified_findings.json"
            if not project.legacy_import and not verified_path.is_file():
                write_verified_findings(project.topic_dir)
            write_evidence_review(
                project.topic_dir,
                landmark_list_path=landmark_list,
            )
        except (OSError, ValueError) as exc:
            _fail(f"Could not refresh evidence review: {exc}", json_output)
    gate = review_gate(project, target)
    messages = {
        "question": "Question reviewed; HARD STOP until the user explicitly approves it.",
        "evidence": (
            "Evidence reviewed; HARD STOP — present evidence_review.json to the user "
            "and use AskUserQuestion. Do NOT begin analysis or load Results phases "
            "until the user explicitly chooses to proceed."
        ),
        "results": ("Results QA passed; ready for review only. No artifacts were uploaded."),
    }
    next_actions = {
        "question": (
            "STOP. Present the Question checkpoint to the user with AskUserQuestion. "
            "After explicit approval Claude runs "
            + routine_command(
                "approve-question",
                directory=project.topic_dir,
            )
        ),
        "evidence": (
            "STOP. Present evidence_review.json to the user with AskUserQuestion. "
            "After an explicit analyze choice Claude runs "
            + routine_command("analyze", directory=project.topic_dir)
        ),
        "results": ("Ask the user whether to revise, reopen Evidence, stop, or publish"),
    }
    if gate.ok and (
        project.status != "awaiting_user" or project.next_action != next_actions[target]
    ):
        project.status = "awaiting_user"
        project.next_action = next_actions[target]
        try:
            store.save(project)
        except AnalysisStateError as exc:
            _fail(str(exc), json_output)
    message = (
        messages[target] if gate.ok else f"{target.capitalize()} review blocked; no transition."
    )
    _exit_if_blocked(project, gate, json_output, message)


