@approve_group.command("question")
@click.option("--dir", "directory", type=click.Path(path_type=Path))
@click.option("--json", "json_output", is_flag=True, help="Emit machine-readable JSON.")
def approve_question_command(directory: Path | None, json_output: bool) -> None:
    """Approve the question artifacts and advance to evidence."""
    store = AnalysisProjectStore()
    project = _load_project(store, directory, json_output)
    project, gate, changed = approve_question(project)
    if gate.ok and changed:
        try:
            store.save(project)
            store.set_active(project.topic_dir)
        except AnalysisStateError as exc:
            _fail(str(exc), json_output)
    _emit_checkpoint(
        project,
        json_output,
        message=(
            "Question approved. Stage is now Evidence. "
            "STOP — do NOT begin searching or extracting yet. "
            "Load phase-03-extraction-guidance next via "
            "`paperclip routines show <routine>/phases/phase-03-extraction-guidance`."
        )
        if changed
        else "Question approval unchanged.",
        changed=changed,
        gate=gate,
    )
    if not gate.ok:
        raise click.exceptions.Exit(1)


@analysis_group.command("revise")
@click.argument(
    "stage",
    required=False,
    type=click.Choice(["question", "evidence", "results"]),
)
@click.option(
    "--stage",
    "stage_option",
    type=click.Choice(["question", "evidence", "results"]),
    help="Stage to revise (alternative to the positional argument).",
)
@click.option("--question", help="Replacement question when revising question.")
@click.option(
    "--reason",
    help="Reason for the revision (required when revising results).",
)
@click.option("--dir", "directory", type=click.Path(path_type=Path))
@click.option("--json", "json_output", is_flag=True, help="Emit machine-readable JSON.")
def revise_command(
    stage: str | None,
    stage_option: str | None,
    question: str | None,
    reason: str | None,
    directory: Path | None,
    json_output: bool,
) -> None:
    """Open a stage for revision and invalidate its dependent approvals."""
    if stage and stage_option and stage != stage_option:
        _fail("Positional stage and --stage disagree.", json_output)
    store = AnalysisProjectStore()
    project = _load_project(store, directory, json_output)
    target = stage_option or stage or project.stage
    archive: dict[str, Any] | None = None
    if target == "results" and not (reason or "").strip():
        _fail("--reason is required when revising results.", json_output)
    try:
        if target not in ("question", "evidence", "results"):
            raise ValueError(f"Unknown stage {target!r}")
        if ("question", "evidence", "results").index(target) > (
            "question",
            "evidence",
            "results",
        ).index(project.stage):
            raise ValueError(
                f"Cannot revise future stage {target!r} while project is at {project.stage!r}"
            )
        if project.stage == "results":
            archive = archive_results_revision(
                project,
                reason or f"Reopened {target} stage.",
            )
        revise_project(project, target, question)
        if archive is not None:
            project.results_revision += 1
        if target == "results":
            project.results_binding = build_results_binding(
                project,
                reason=(reason or "").strip(),
            )
        store.save(project)
        store.set_active(project.topic_dir)
    except (ValueError, AnalysisStateError, ReportStateError, OSError) as exc:
        _fail(str(exc), json_output)
    _emit_checkpoint(
        project,
        json_output,
        message=f"{target.capitalize()} opened for revision; downstream approvals invalidated.",
        changed=True,
        extra={
            "results_archive": archive["archive"] if archive else None,
            "results_revision": project.results_revision,
        },
    )


