@analysis_group.command("pilot-compare")
@click.option(
    "--structured-manifest",
    "structured_paths",
    required=True,
    multiple=True,
    type=click.Path(path_type=Path),
)
@click.option(
    "--exhaustive-manifest",
    "exhaustive_paths",
    required=True,
    multiple=True,
    type=click.Path(path_type=Path),
)
@click.option(
    "--structured-verifier-pass-rate",
    type=click.FloatRange(0.0, 1.0),
)
@click.option(
    "--exhaustive-verifier-pass-rate",
    type=click.FloatRange(0.0, 1.0),
)
@click.option("--dir", "directory", type=click.Path(path_type=Path))
@click.option("--json/--human", "json_output", default=True)
def pilot_compare_command(
    structured_paths: tuple[Path, ...],
    exhaustive_paths: tuple[Path, ...],
    structured_verifier_pass_rate: float | None,
    exhaustive_verifier_pass_rate: float | None,
    directory: Path | None,
    json_output: bool,
) -> None:
    """Compare structured pilot extraction with the exhaustive reference."""
    project = _load_project(AnalysisProjectStore(), directory, json_output)

    def load(paths: tuple[Path, ...], label: str) -> list[dict[str, Any]]:
        manifests = []
        for path in paths:
            try:
                value = json.loads(path.expanduser().read_text(encoding="utf-8"))
            except (OSError, json.JSONDecodeError) as exc:
                _fail(f"Could not read {label} manifest {path}: {exc}", json_output)
            if not isinstance(value, dict):
                _fail(f"{label} manifest {path} must contain one JSON object.", json_output)
            manifests.append(value)
        return manifests

    try:
        artifact = write_pilot_comparison(
            project.topic_dir,
            load(structured_paths, "structured"),
            load(exhaustive_paths, "exhaustive"),
            structured_verifier_pass_rate=structured_verifier_pass_rate,
            exhaustive_verifier_pass_rate=exhaustive_verifier_pass_rate,
        )
    except (OSError, PilotComparisonError, ValueError) as exc:
        _fail(str(exc), json_output)
    if json_output:
        click.echo(json.dumps({"ok": True, **artifact}, indent=2, sort_keys=True))
    else:
        click.echo("[pilot comparison]")
        click.echo(f"status: {artifact['status']}")
        click.echo(f"field recall: {artifact['field_recall']}")
        click.echo(f"value agreement: {artifact['value_agreement']}")
        click.echo(f"source-location agreement: {artifact['source_location_agreement']}")


