@analysis_group.command("resume")
@click.argument("path", required=False, type=click.Path(path_type=Path))
@click.option("--dir", "directory", type=click.Path(path_type=Path))
@click.option("--json", "json_output", is_flag=True, help="Emit machine-readable JSON.")
def resume_command(
    path: Path | None,
    directory: Path | None,
    json_output: bool,
) -> None:
    """Select an existing local analysis project as active."""
    if path and directory and path.expanduser().resolve() != directory.expanduser().resolve():
        _fail("PATH and --dir refer to different projects.", json_output)
    store = AnalysisProjectStore()
    selected = directory or path
    project = _load_project(store, selected, json_output)
    try:
        if project.status != "awaiting_user":
            next_action = next_action_for_stage(project)
            if project.next_action != next_action:
                project.next_action = next_action
                store.save(project)
        store.set_active(project.topic_dir)
    except AnalysisStateError as exc:
        _fail(str(exc), json_output)
    _emit_checkpoint(project, json_output, message="Analysis project resumed.", changed=True)


@analysis_group.command("fork")
@click.argument("slug")
@click.option(
    "--dir",
    "target_dir",
    required=True,
    type=click.Path(path_type=Path),
    help="New local topic directory.",
)
@click.option("--from-dir", "source_dir", type=click.Path(path_type=Path))
@click.option("--repo", "--repo-name", "repo_name", default=None)
@click.option("--json", "json_output", is_flag=True, help="Emit machine-readable JSON.")
def fork_command(
    slug: str,
    target_dir: Path,
    source_dir: Path | None,
    repo_name: str | None,
    json_output: bool,
) -> None:
    """Copy a project and its artifacts into an independent local project."""
    slug = _normal_slug(slug, json_output)
    store = AnalysisProjectStore()
    parent = _load_project(store, source_dir, json_output)
    source = Path(parent.topic_dir).resolve()
    target = target_dir.expanduser().resolve()
    normalized_repo = (repo_name or slug).strip()
    if not normalized_repo:
        _fail("Repository name cannot be empty.", json_output)
    if target == source or source in target.parents:
        _fail("Fork target must be outside the parent project directory.", json_output)
    if target.exists():
        if not target.is_dir():
            _fail(f"Fork target is not a directory: {target}", json_output)
        if any(target.iterdir()):
            _fail(f"Fork target must be empty: {target}", json_output)
    else:
        try:
            target.mkdir(parents=True)
        except OSError as exc:
            _fail(f"Cannot create fork target {target}: {exc}", json_output)

    try:
        for child in source.iterdir():
            if child.name == "analysis_project.json":
                continue
            destination = target / child.name
            if child.is_dir():
                shutil.copytree(child, destination)
            elif child.is_file():
                shutil.copy2(child, destination)
    except OSError as exc:
        _fail(f"Could not copy project artifacts: {exc}", json_output)

    now = utc_now()
    child_project = AnalysisProject(
        project_id=str(uuid.uuid4()),
        parent_id=parent.project_id,
        slug=slug,
        topic_dir=str(target),
        question=parent.question,
        repo=RepositoryRef(
            name=normalized_repo,
            branch=parent.repo.branch,
            sha=parent.repo.sha,
        ),
        legacy_import=parent.legacy_import,
        revision=1,
        created_at=now,
        updated_at=now,
    )
    child_project.next_action = next_action_for_stage(child_project)
    try:
        store.save(child_project, touch=False)
        store.set_active(target)
    except AnalysisStateError as exc:
        _fail(str(exc), json_output)
    _emit_checkpoint(
        child_project,
        json_output,
        message=f"Forked from {parent.slug}; copied artifacts require fresh approval.",
        changed=True,
    )


@analysis_group.command("preview")
@click.option("--dir", "directory", type=click.Path(path_type=Path))
@click.option("--serve", is_flag=True, help="Serve the project directory until interrupted.")
@click.option(
    "--print-only",
    is_flag=True,
    help="Validate and print the preview URL without starting a server.",
)
@click.option("--port", default=8008, show_default=True, type=click.IntRange(1, 65535))
@click.option("--json", "json_output", is_flag=True, help="Emit machine-readable JSON.")
def preview_command(
    directory: Path | None,
    serve: bool,
    print_only: bool,
    port: int,
    json_output: bool,
) -> None:
    """Validate index.html and optionally serve it locally; never uploads."""
    project = _load_project(AnalysisProjectStore(), directory, json_output)
    index = Path(project.topic_dir) / "index.html"
    if not index.is_file():
        _fail(f"Preview requires {index}.", json_output)
    try:
        sample = index.read_text(encoding="utf-8")
    except (OSError, UnicodeDecodeError) as exc:
        _fail(f"Cannot read index.html: {exc}", json_output)
    if not sample.strip() or "<html" not in sample.lower():
        _fail("index.html is empty or does not contain an <html> document.", json_output)

    url = f"http://127.0.0.1:{port}/index.html"
    if json_output:
        payload = project.summary()
        payload.update(
            {
                "ok": True,
                "message": "Preview validated locally; no artifacts were uploaded.",
                "preview_url": url,
                "uploaded": False,
            }
        )
        click.echo(json.dumps(payload, indent=2, sort_keys=True))
    else:
        _emit_checkpoint(project, False, message=f"Preview validated: {index}")
        click.echo(f"preview: {url}")

    if not serve or print_only:
        return
    handler = partial(SimpleHTTPRequestHandler, directory=project.topic_dir)
    try:
        with ThreadingHTTPServer(("127.0.0.1", port), handler) as server:
            server.serve_forever()
    except KeyboardInterrupt:
        return
    except OSError as exc:
        _fail(f"Could not start preview server: {exc}", json_output)


@analysis_group.command("publish")
@click.option("--dry-run", is_flag=True, help="Validate and print uploads without writing files.")
@click.option(
    "--record-uploaded",
    is_flag=True,
    help="Record success after the standard paperclip upload command completes.",
)
@click.option("--dir", "directory", type=click.Path(path_type=Path))
@click.option("--json", "json_output", is_flag=True, help="Emit machine-readable JSON.")
def publish_command(
    dry_run: bool,
    record_uploaded: bool,
    directory: Path | None,
    json_output: bool,
) -> None:
    """Validate and prepare a versioned upload for Claude to publish."""
    if dry_run and record_uploaded:
        _fail("--dry-run and --record-uploaded cannot be used together.", json_output)
    store = AnalysisProjectStore()
    project = _load_project(store, directory, json_output)
    gate, inventory = validate_publish(project)
    if not gate.ok:
        _emit_checkpoint(
            project,
            json_output,
            message="Publish validation blocked.",
            changed=False,
            gate=gate,
            inventory=inventory,
        )
        raise click.exceptions.Exit(1)
    destination = f"analyses/{project.slug}/v{project.results_revision}"
    hashes = {item["path"]: item["sha256"] for item in inventory}
    previous = publication_for_revision(project)
    if previous is not None:
        if previous.get("artifact_hashes") != hashes:
            _fail(
                "This results revision was already published with different artifacts. "
                "Claude must run "
                + routine_command(
                    "revise",
                    "results",
                    "--reason",
                    "<text>",
                    directory=project.topic_dir,
                )
                + " before publishing another version.",
                json_output,
            )
        _emit_checkpoint(
            project,
            json_output,
            message="Current results revision is already published; no files uploaded.",
            changed=False,
            gate=gate,
            inventory=inventory,
            extra={
                "destination": destination,
                "published": True,
                "idempotent": True,
                "publish_manifest_sha256": previous.get("publish_manifest_sha256"),
            },
        )
        return

    root = Path(project.topic_dir)
    manifest_path = root / "publish_manifest.json"
    upload_files = [str(root / item["path"]) for item in inventory]
    upload_files.append(str(manifest_path))
    upload_command = shlex.join(["paperclip", "upload", *upload_files, "--into", destination])

    if dry_run:
        dry_manifest = build_publish_manifest(
            project,
            inventory,
            status="dry_run",
        )
        _emit_checkpoint(
            project,
            json_output,
            message=(
                f"Publish dry run passed for /clipboard/{destination}/; no artifacts were uploaded."
            ),
            changed=False,
            gate=gate,
            inventory=inventory,
            extra={
                "destination": destination,
                "published": False,
                "dry_run": True,
                "manifest": dry_manifest,
                "upload_files": upload_files,
                "upload_command": upload_command,
            },
        )
        return

    manifest: dict[str, Any] | None = None
    if manifest_path.is_file():
        try:
            loaded = json.loads(manifest_path.read_text(encoding="utf-8"))
        except (OSError, json.JSONDecodeError):
            loaded = None
        if isinstance(loaded, dict):
            manifest = loaded
    expected_manifest_fields = {
        "schema_version": 1,
        "project_id": project.project_id,
        "slug": project.slug,
        "project_revision": project.revision,
        "results_revision": project.results_revision,
        "destination": destination,
        "status": "published",
        "results_binding": project.results_binding,
        "artifact_hashes": hashes,
        "artifacts": inventory,
    }
    manifest_is_current = manifest is not None and all(
        manifest.get(key) == value for key, value in expected_manifest_fields.items()
    )

    if not record_uploaded:
        if not manifest_is_current:
            manifest = build_publish_manifest(project, inventory, status="published")
            try:
                manifest_path = write_publish_manifest(project, manifest)
            except OSError as exc:
                _fail(f"Could not prepare publish manifest: {exc}", json_output)
        manifest_hash = sha256_file(manifest_path)
        _emit_checkpoint(
            project,
            json_output,
            message=(
                "Publish validation passed and publish_manifest.json was prepared. "
                "No artifacts were uploaded; Claude must run the returned standard "
                "paperclip upload command."
            ),
            changed=False,
            gate=gate,
            inventory=inventory,
            extra={
                "destination": destination,
                "published": False,
                "prepared": True,
                "upload_files": upload_files,
                "upload_command": upload_command,
                "publish_manifest_sha256": manifest_hash,
            },
        )
        return

    if not manifest_is_current:
        _fail(
            "No current prepared publish_manifest.json exists. Run "
            + routine_command("publish", directory=project.topic_dir)
            + " before paperclip upload, then record the successful upload.",
            json_output,
        )

    manifest_hash = sha256_file(manifest_path)
    publication = {
        "status": "published",
        "published_at": utc_now(),
        "destination": destination,
        "results_revision": project.results_revision,
        "artifact_hashes": hashes,
        "publish_manifest_sha256": manifest_hash,
    }
    project.publications.append(publication)
    project.status = "published"
    project.next_action = (
        "published; Claude uses "
        + routine_command(
            "revise",
            "results",
            "--reason",
            "<text>",
            directory=project.topic_dir,
        )
        + " for another version"
    )
    try:
        store.save(project)
    except AnalysisStateError as exc:
        _fail(str(exc), json_output)
    _emit_checkpoint(
        project,
        json_output,
        message=f"Recorded successful versioned upload to /clipboard/{destination}/.",
        changed=True,
        gate=gate,
        inventory=inventory,
        extra={
            "destination": destination,
            "published": True,
            "idempotent": False,
            "publish_manifest_sha256": manifest_hash,
        },
    )


