@analysis_group.command("scaffold")
@click.option(
    "--dir",
    "directory",
    required=True,
    type=click.Path(path_type=Path),
    help="Local topic directory.",
)
@click.option(
    "--file",
    "file_name",
    required=True,
    type=click.Choice(sorted(_SCAFFOLDS)),
    help="Which artifact to scaffold.",
)
@click.option("--force", is_flag=True, help="Overwrite an existing file.")
@click.option("--json", "json_output", is_flag=True, help="Emit machine-readable JSON.")
def scaffold_command(
    directory: Path,
    file_name: str,
    force: bool,
    json_output: bool,
) -> None:
    """Generate a valid starter JSON file for a contract-validated artifact.

    Writes a template that passes structural validation. Replace every FILL
    placeholder with project-specific content.
    """
    entry = _SCAFFOLDS.get(file_name)
    if entry is None:
        _fail(f"Unknown scaffold file: {file_name}", json_output)
    filename, template = entry
    directory = directory.expanduser().resolve()
    directory.mkdir(parents=True, exist_ok=True)
    target = directory / filename
    if target.exists() and not force:
        _fail(
            f"{target} already exists. Use --force to overwrite.",
            json_output,
        )
    scaffold = json.loads(json.dumps(template))
    if file_name == "harmonization_map":
        queue_path = directory / "harmonization_queue.json"
        scaffold["harmonization_queue_sha256"] = (
            sha256_file(queue_path) if queue_path.is_file() else None
        )
    content = json.dumps(scaffold, indent=2, ensure_ascii=False, sort_keys=False)
    target.write_text(content + "\n", encoding="utf-8")
    if json_output:
        click.echo(
            json.dumps(
                {
                    "ok": True,
                    "file": str(target),
                    "artifact": file_name,
                    "message": "Scaffold written. Replace FILL placeholders with project values.",
                },
                indent=2,
            )
        )
    else:
        click.echo(f"Wrote {target}")
        click.echo("Replace every FILL placeholder with project-specific content.")
